cat > candidate.mjs <<'EOF'
let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const json = { "content-type": "application/json" };
const { transferId, idempotencyKey, fromId, toId, amount } = input;
const fromBalance = input.fromBalance;
const toBalance = input.toBalance;
const fromVersion = input.fromVersion;
const toVersion = input.toVersion;

const accountsUnchanged = () => [
  { id: fromId, balance: fromBalance, version: fromVersion },
  { id: toId, balance: toBalance, version: toVersion }
];

function out(status, body, { accounts = accountsUnchanged(), committed = false, messages = [], ordering = [], failures = [], retryable = false } = {}) {
  console.log(JSON.stringify({
    http: { status, headers: json, body },
    database: { accounts, transaction: { committed, rolledBack: !committed && failures.length > 0 } },
    messages,
    ordering,
    failures,
    retryability: retryable
  }));
}

function fail(status, code, retryable) {
  out(status, { error: code, retryable }, { failures: [{ code, status, retryable }], retryable });
}

// Prior outcome recorded for this idempotency key (replay).
const prior = input.existingTransfer ?? input.replay ?? input.processed?.[idempotencyKey];

if (prior) {
  out(200, { ...prior, transferId: prior.transferId ?? transferId, replayed: true }, {
    ordering: ["idempotency-check"]
  });
} else if (!Number.isInteger(amount) || amount <= 0 || !fromId || !toId || fromId === toId) {
  fail(400, "invalid_request", false);
} else if (
  (input.expectedFromVersion !== undefined && input.expectedFromVersion !== fromVersion) ||
  (input.expectedToVersion !== undefined && input.expectedToVersion !== toVersion)
) {
  fail(409, "version_conflict", true);
} else if (fromBalance < amount) {
  fail(422, "insufficient_funds", false);
} else {
  const newFrom = fromBalance - amount;
  const newTo = toBalance + amount;
  const event = { type: "transfer.completed", transferId, idempotencyKey, fromId, toId, amount };
  out(200, { transferId, fromBalance: newFrom, toBalance: newTo, fromVersion: fromVersion + 1, toVersion: toVersion + 1, replayed: false }, {
    accounts: [
      { id: fromId, balance: newFrom, version: fromVersion + 1 },
      { id: toId, balance: newTo, version: toVersion + 1 }
    ],
    committed: true,
    messages: [event],
    ordering: ["idempotency-check", "debit", "credit", "commit", "publish"]
  });
}
EOF
